# filename: app/core/metrics.py
# Code Generated by Sidekick is for learning and experimentation purposes only.

from prometheus_client import Counter, Histogram, Gauge, generate_latest, CONTENT_TYPE_LATEST
from fastapi import Response

# Booking metrics
booking_counter = Counter(
    'booking_requests_total',
    'Total number of booking requests',
    ['status']
)

booking_duration_histogram = Histogram(
    'booking_duration_seconds',
    'Booking request duration in seconds',
    buckets=[0.1, 0.5, 1, 2, 5, 10, 30]
)

booking_errors_counter = Counter(
    'booking_errors_total',
    'Total number of booking errors',
    ['error_type']
)

# Lock metrics
lock_contention_counter = Counter(
    'lock_contention_total',
    'Total number of lock contention events'
)

lock_acquisition_histogram = Histogram(
    'lock_acquisition_duration_ms',
    'Time taken to acquire lock in milliseconds',
    buckets=[10, 50, 100, 200, 500, 1000, 2000]
)

# Database metrics
db_connection_gauge = Gauge(
    'db_connections_active',
    'Number of active database connections'
)

# Rate limit metrics
rate_limit_counter = Counter(
    'rate_limit_hits_total',
    'Total number of rate limit hits'
)


def metrics_endpoint():
    """Prometheus metrics endpoint"""
    return Response(
        content=generate_latest(),
        media_type=CONTENT_TYPE_LATEST
    )
